customCSS:
.t, .history { color: #666666; }
.join { color: #c9d05c; }
.part, .quit { color: #666666; }
.kick, .error { color: #f43753; }
.notice { color: #d3b987; }
.action { color: #d3b987; }
.mode, .nick, .topic, .server { color: #b3deef; }
.highlight { color: #eeeeee; background-color: #293b44; border-left: 3px solid #d3b987; padding-left: 8px; }
.reply { color: #666666; border-left: 2px solid #73cef4; padding-left: 6px; }
.oper { color: #282828; background-color: #d3b987; }
.reactions { color: #73cef4; background-color: #383838; }
.card { background-color: #383838; border-color: #666666; }
.card-title { color: #73cef4; }
.card-desc { color: #666666; }
.daychange { color: #666666; border-color: #383838; }
